def _arrow(ov, p0, p1, col, k, dashed=False, w=16):
    p1 = (int(p0[0] + (p1[0] - p0[0]) * k), int(p0[1] + (p1[1] - p0[1]) * k))
    if dashed:
        n = 14
        for i in range(n):
            if i % 2: continue
            a = i / n; b = (i + 1) / n
            cv2.line(ov, (int(p0[0] + (p1[0] - p0[0]) * a), int(p0[1] + (p1[1] - p0[1]) * a)), (int(p0[0] + (p1[0] - p0[0]) * b), int(p0[1] + (p1[1] - p0[1]) * b)), col, w, cv2.LINE_AA)
    else: cv2.line(ov, p0, p1, col, w, cv2.LINE_AA)
