        pts = np.array([p1, (int(p1[0] - h * math.cos(ang - 0.45)), int(p1[1] - h * math.sin(ang - 0.45))), (int(p1[0] - h * math.cos(ang + 0.45)), int(p1[1] - h * math.sin(ang + 0.45)))], np.int32)
