    if S.get('endcard'):
        k = min(1, u / 0.3); img = cv2.addWeighted(img, 1 - 0.4 * k, np.zeros_like(img), 0.4 * k, 0)
    paste(img, bug, 966, 330, 1.0, 0.9)                                     # small logo bug, top right
    ff.stdin.write(np.ascontiguousarray(img).tobytes())
